  "python_source": "import datetime
import re
from collections import Counter, defaultdict

def safe_float(value, default=0.0):
    try:
        return float(value)
    except (TypeError, ValueError):
        return default

def safe_int(value, default=0):
    try:
        return int(value)
    except (TypeError, ValueError):
        return default

def get_nested(d, *keys, default=None):
    current = d
    for k in keys:
        if not isinstance(current, dict):
            return default
        current = current.get(k, None)
        if current is None:
            return default
    return current

def iso_to_epoch(ts_str, default=None):
    if not ts_str:
        return default
    try:
        dt = datetime.datetime.fromisoformat(ts_str.replace('Z', '+00:00'))
        return dt.timestamp()
    except (ValueError, TypeError):
        return default

metrics = ops.query_metrics(service="checkout", window="6h")
logs = ops.query_logs(service="checkout", severity="error", window="6h")
deployment = ops.latest_deployment(repository="shop/checkout")
config = ops.read_deployment(cluster="prod-eu", namespace="checkout")

# Extract metrics with safe defaults
series = metrics.get('series', [])
metric_points = defaultdict(list)
for entry in series:
    name = entry.get('name') or entry.get('metric')
    if not name:
        continue
    points = entry.get('points') or []
    for point in points:
        if not isinstance(point, dict):
            continue
        ts = iso_to_epoch(point.get('timestamp'), None)
        val = safe_float(point.get('value'))
        if ts is None or val is None:
            continue
        metric_points[name].append((ts, val))

# Time bucket aggregation (5-minute buckets for 6h = 72 buckets)
bucket_size = 300  # seconds
end_time = max((ts for pts in metric_points.values() for ts, _ in pts), default=0)
start_time = min((ts for pts in metric_points.values() for ts, _ in pts), default=0)
if end_time <= start_time:
    end_time = start_time + 6 * 3600
    start_time = end_time - 6 * 3600

bucket_counts = int((end_time - start_time) / bucket_size) + 1

def bucket_point(ts):
    idx = int((ts - start_time) / bucket_size)
    return max(0, min(bucket_counts - 1, idx))

def aggregate_series(points, aggregator):
    buckets = {}
    for ts, val in points:
        idx = bucket_point(ts)
        if idx not in buckets:
            buckets[idx] = []
        buckets[idx].append(val)
    result = []
    for idx in range(bucket_counts):
        vals = buckets.get(idx, [])
        if vals:
            if aggregator == 'avg':
                result.append(sum(vals) / len(vals))
            elif aggregator == 'max':
