    vals = [v for v in series if v is not None]
    if not vals:
        return {'min': None, 'max': None, 'avg': None, 'p95': None}
    vals_sorted = sorted(vals)
    return {
        'min': min(vals),
        'max': max(vals),
        'avg': sum(vals) / len(vals),
        'p95': vals_sorted[int(0.95 * (len(vals) - 1))]
