secret_expected = ['database_url', 'api_key']
secret_missing = [s for s in secret_expected if s not in secrets]
if secret_missing:
    config_drifts.append(f"Missing secrets: {', '.join(secret_missing)}")

# Threshold evaluation
thresholds = {
    'error_rate_percent': 1.0,
    'p99_latency_ms': 500,
    'error_count_per_hour': 100
}
# Calculate error rate percent from logs (errors / requests)
req_per_hour = avg_req_per_sec * 3600 if avg_req_per_sec else 0
error_rate_percent = 0.0
if req_per_hour > 0:
    error_rate_percent = (errors_per_hour / req_per_hour) * 100

violations = []
if err_stats['avg'] is not None and err_stats['avg'] > thresholds['error_rate_percent']:
    violations.append(f"error_rate avg {err_stats['avg']:.2f}% > {thresholds['error_rate_percent']}%")
if lat_stats['max'] is not None and lat_stats['max'] > thresholds['p99_latency_ms']:
    violations.append(f"p99_latency max {lat_stats['max']:.0f}ms > {thresholds['p99_latency_ms']}ms")
if errors_per_hour > thresholds['error_count_per_hour']:
    violations.append(f"error count {errors_per_hour:.0f}/h > {thresholds['error_count_per_hour']}/h")

# Deployment correlation
deploy_correlations = {
    'deployment_status': deploy_status,
    'deploy_sha': deploy_sha,
    'deploy_time': deploy_time_str,
    'deploy_age_minutes': (datetime.datetime.now().timestamp() - deploy_time) / 60 if deploy_time else None
}

# Evidence table (list of dicts)
evidence_table = []
evidences = [
    {"id": "E1", "type": "metric", "source": "request_rate", "value": req_stats['avg'], "status": "ok" if req_stats['avg'] is not None else "missing"},
    {"id": "E2", "type": "metric", "source": "error_rate", "value": err_stats['avg'], "status": "ok" if err_stats['avg'] is not None else "missing"},
    {"id": "E3", "type": "metric", "source": "p99_latency", "value": lat_stats['max'], "status": "ok" if lat_stats['max'] is not None else "missing"},
    {"id": "L1", "type": "log", "source": "error_logs", "value": total_errors, "status": "ok" if total_errors > 0 else "no errors"},
    {"id": "D1", "type": "deployment", "source": "latest", "value": deploy_sha, "status": deploy_status},
    {"id": "C1", "type": "config", "source": "config_map", "value": config_map, "status": "drift" if config_drifts else "ok"}
]
for ev in evidences:
    if ev["value"] is None and ev["type"] == "metric":
        ev["status"] = "missing"
    evidence_table.append(ev)

# Confidence scoring (weighted)
metric_available = sum(1 for ev in evidence_table if ev["type"] == "metric" and ev["value"] is not None)
log_available = 1 if total_errors > 0 else 0
deploy_available = 1 if deploy_sha else 0
config_available = 1 if config_map else 0
available_count = metric_available + log_available + deploy_available + config_available
total_inputs = 4  # metrics, logs, deployment, config
coverage = available_count / total_inputs if total_inputs > 0 else 0.0

# Severity from violations
severity_score = 0
if len(violations) > 0:
    severity_score += min(10, len(violations) * 3)
if len(config_drifts) > 0:
    severity_score += 2
if deploy_status != 'success':
    severity_score += 2
confidence = 0.5 + 0.5 * coverage - 0.1 * severity_score
confidence = max(0.0, min(1.0, confidence))

# Release gate decision
release_gate = "GO" if (len(violations) == 0 and len(config_drifts) == 0 and deploy_status == "success" and confidence >= 0.7) else "NO-GO"

# Build final report
report = {
    "service": "checkout",
    "analysis_window": "6h",
    "generated_at": datetime.datetime.utcnow().isoformat() + "Z",
    "metrics_summary": {
        "request_rate": req_stats,
        "error_rate": err_stats,
        "p99_latency_ms": lat_stats
    },
    "error_summary": {
        "total_errors": total_errors,
        "errors_per_hour": errors_per_hour,
        "error_type_counts": dict(error_type_counts)
    },
    "deployment": deploy_correlations,
    "config_drifts": config_drifts,
    "threshold_violations": violations,
    "evidence_table": evidence_table,
    "confidence_score": confidence,
    "release_gate": release_gate
}

result = report"
