        "image": safe_get(raw, "image", "unknown"),
        "timestamp": safe_get(raw, "timestamp", 0.0),
        "version": safe_get(raw, "version", "unknown")
    }

deployment_norm = normalize_deployment(deployment)

# Normalize config
def normalize_config(raw):
    if not isinstance(raw, dict):
        return {}
    data = safe_get(raw, "data", {})
    if not isinstance(data, dict):
        return {}
    return {k: str(v) for k, v in data.items()}

config_norm = normalize_config(config)

# Time bucket aggregation: assume window 6h, bucket size 5 min = 300s
bucket_size = 300.0
start_time = None
end_time = None
if metrics_norm:
    all_ts = []
    for points in metrics_norm.values():
        for (ts, val) in points:
            all_ts.append(ts)
    if all_ts:
        start_time = min(all_ts)
        end_time = max(all_ts)

if start_time is None or end_time is None:
    start_time = 0.0
    end_time = start_time + 6 * 3600

num_buckets = int((end_time - start_time) / bucket_size) + 1

# Initialize buckets for metrics
def make_bucket_map():
    return {
        "error_rate": [0.0] * num_buckets,
        "latency_p95": [0.0] * num_buckets,
        "throughput": [0.0] * num_buckets
    }

bucket_map = make_bucket_map()
bucket_counts = {k: [0] * num_buckets for k in bucket_map}

# Aggregate metrics into buckets
def bucket_index(ts):
    idx = int((ts - start_time) / bucket_size)
    return max(0, min(num_buckets - 1, idx))

for name, points in metrics_norm.items():
    for (ts, val) in points:
        idx = bucket_index(ts)
        if "error_rate" in name:
            bucket_map["error_rate"][idx] += val
            bucket_counts["error_rate"][idx] += 1
        elif "latency" in name and "p95" in name:
            bucket_map["latency_p95"][idx] += val
            bucket_counts["latency_p95"][idx] += 1
        elif "throughput" in name or "rps" in name:
            bucket_map["throughput"][idx] += val
            bucket_counts["throughput"][idx] += 1

# Average the buckets to get per-bucket values
for key in bucket_map:
    for i in range(num_buckets):
        cnt = bucket_counts[key][i]
        if cnt > 0:
            bucket_map[key][i] = bucket_map[key][i] / cnt

# Compute overall metrics
def overall_metric(bucket_list):
    non_zero = [v for v in bucket_list if v > 0]
    if not non_zero:
        return 0.0
    return sum(non_zero) / len(non_zero)

overall_error_rate = overall_metric(bucket_map["error_rate"])
overall_latency = overall_metric(bucket_map["latency_p95"])
overall_throughput = overall_metric(bucket_map["throughput"])

# Error grouping

def group_errors(log_entries):
    groups = {}
    for entry in log_entries:
        msg = entry["message"]
        # simple signature: first 100 chars or pattern
        sig = msg[:100] if len(msg) >= 100 else msg
        if sig not in groups:
            groups[sig] = {"count": 0, "last_seen": entry["timestamp"], "first_seen": entry["timestamp"], "messages": []}
        groups[sig]["count"] += 1
        groups[sig]["last_seen"] = max(groups[sig]["last_seen"], entry["timestamp"])
        groups[sig]["first_seen"] = min(groups[sig]["first_seen"], entry["timestamp"])
        if len(groups[sig]["messages"]) < 5:
            groups[sig]["messages"].append(entry["message"])
    return groups

error_groups = group_errors(logs_norm)

# Sort groups by count descending
error_groups_sorted = sorted(error_groups.items(), key=lambda item: item[1]["count"], reverse=True)

# Deployment correlation: find deploy time, compare to error spikes

deploy_ts = deployment_norm.get("timestamp", 0.0)

# Create error time series from logs
error_times = [entry["timestamp"] for entry in logs_norm]

# Check if error_rate spiked near deployment
def has_spike_near_deploy(error_series, deploy_ts, window=300.0):
    if not error_series:
        return False
    near_deploy = [ts for ts in error_series if abs(ts - deploy_ts) <= window]
    if not near_deploy:
        return False
    # count errors near deploy vs overall rate
    near_count = len(near_deploy)
    total_count = len(error_series)
    return near_count > 0 and total_count > 0 and (near_count / total_count) > 0.3

correlation_with_deploy = has_spike_near_deploy(error_times, deploy_ts)

# Configuration drift checks

def config_drift(normalized_config, required_keys):
    missing = []
    for key in required_keys:
        if key not in normalized_config:
            missing.append(key)
    return missing

required_config = ["feature_flags", "database_timeout", "cache_ttl"]
missing_config = config_drift(config_norm, required_config)

# Threshold evaluation

thresholds = {
    "error_rate": 0.05,  # 5%
    "latency_p95": 500.0,  # ms
    "throughput_min": 100.0,  # rps
}

error_rate_ok = overall_error_rate <= thresholds["error_rate"]
latency_ok = overall_latency <= thresholds["latency_p95"]
throughput_ok = overall_throughput >= thresholds["throughput_min"]

# Evaluate on bucket level too for spikes

def has_bucket_violation(bucket_list, threshold, is_upper=True):
    for v in bucket_list:
        if v > 0:
            if is_upper and v > threshold:
                return True
            if not is_upper and v < threshold:
                return True
    return False

bucket_error_violation = has_bucket_violation(bucket_map["error_rate"], thresholds["error_rate"])
bucket_latency_violation = has_bucket_violation(bucket_map["latency_p95"], thresholds["latency_p95"])
bucket_throughput_violation = has_bucket_violation(bucket_map["throughput"], thresholds["throughput_min"], is_upper=False)

# Evidence table construction

evidence_table = []

if error_groups_sorted:
    group = error_groups_sorted[0][1]
    evidence_table.append({
        "type": "error_group",
        "description": "Most frequent error",
        "detail": group["messages"][0] if group["messages"] else "No message",
        "count": group["count"],
        "severity": "high" if group["count"] > 100 else "medium"
    })

if correlation_with_deploy:
    evidence_table.append({
        "type": "correlation",
        "description": "Error spike near deployment",
        "detail": f"Deployment at {deploy_ts}",
        "count": 1,
        "severity": "high"
    })

if missing_config:
    evidence_table.append({
        "type": "config_drift",
        "description": "Missing configuration keys",
        "detail": ", ".join(missing_config),
        "count": len(missing_config),
        "severity": "medium"
    })

if bucket_error_violation:
    evidence_table.append({
        "type": "metric_violation",
        "description": "Error rate bucket violation",
        "detail": "Error rate exceeded threshold in some buckets",
        "count": sum(1 for v in bucket_map["error_rate"] if v > thresholds["error_rate"]),
        "severity": "high"
    })

if bucket_latency_violation:
    evidence_table.append({
        "type": "metric_violation",
        "description": "Latency bucket violation",
        "detail": "Latency p95 exceeded threshold in some buckets",
        "count": sum(1 for v in bucket_map["latency_p95"] if v > thresholds["latency_p95"]),
        "severity": "medium"
    })

if bucket_throughput_violation:
    evidence_table.append({
        "type": "metric_violation",
        "description": "Throughput bucket violation",
        "detail": "Throughput below threshold in some buckets",
        "count": sum(1 for v in bucket_map["throughput"] if v < thresholds["throughput_min"]),
        "severity": "low"
    })

# Confidence scoring

score = 0
max_score = 100

if error_rate_ok:
    score += 20
else:
    score -= 20

if latency_ok:
    score += 20
else:
    score -= 10

if throughput_ok:
    score += 10
else:
    score -= 5

if not missing_config:
    score += 10
else:
    score -= 10

if not correlation_with_deploy:
    score += 20
else:
    score -= 20

if len(error_groups_sorted) == 0:
    score += 10
else:
    score -= len(error_groups_sorted) * 2

score = max(0, min(100, score))

# Release gate decisions

gate_passed = score >= 70 and error_rate_ok and latency_ok

if not error_rate_ok:
    gate_blockers = "High error rate"
elif not latency_ok:
    gate_blockers = "High latency"
else:
    gate_blockers = "None"

if missing_config:
    gate_warnings = "Missing configuration keys"
else:
    gate_warnings = "None"

# Final structured report

report = {
    "meta": {
        "service": "checkout",
        "window": "6h",
        "analysis_time": datetime.datetime.utcnow().isoformat() + "Z"
    },
    "inputs": {
        "metrics_series_count": len(metrics_norm),
        "log_entries_count": len(logs_norm),
        "deployment": deployment_norm,
        "config_keys": sorted(config_norm.keys())
    },
    "metrics_summary": {
        "overall_error_rate": overall_error_rate,
        "overall_latency_p95": overall_latency,
        "overall_throughput": overall_throughput,
        "bucket_count": num_buckets
    },
    "error_groups": [
        {"signature": sig, "count": stats["count"], "first_seen": stats["first_seen"], "last_seen": stats["last_seen"]}
        for sig, stats in error_groups_sorted[:10]
    ],
    "deployment_correlation": {
        "deployment_timestamp": deploy_ts,
        "correlated_with_errors": correlation_with_deploy
    },
    "config_checks": {
        "missing_keys": missing_config,
        "drift_detected": bool(missing_config)
    },
    "threshold_evaluation": {
        "error_rate_threshold": thresholds["error_rate"],
        "error_rate_ok": error_rate_ok,
        "latency_threshold": thresholds["latency_p95"],
        "latency_ok": latency_ok,
        "throughput_min": thresholds["throughput_min"],
        "throughput_ok": throughput_ok
    },
    "evidence_table": evidence_table,
    "confidence_score": score,
    "release_gate": {
        "passed": gate_passed,
        "blockers": gate_blockers,
        "warnings": gate_warnings
    }
}

result = report
"
