def safe_get(dictionary, key, default=None):
    if isinstance(dictionary, dict):
        return dictionary.get(key, default)
    return default


def default_metric(metric_name):
    series = safe_get(metrics, metric_name)
    if not isinstance(series, list):
        return []
    result = []
    for point in series:
        if isinstance(point, dict) and 'timestamp' in point:
            result.append(point)
    return result


def default_log_entries():
    if not isinstance(logs, list):
        return []
    result = []
    for entry in logs:
        if isinstance(entry, dict):
            result.append(entry)
    return result


now_timestamp = safe_get(metrics, 'now', default=datetime.datetime.now(datetime.timezone.utc).isoformat())
try:
    now_dt = datetime.datetime.fromisoformat(now_timestamp.replace('Z', '+00:00'))
except Exception:
    now_dt = datetime.datetime.now(datetime.timezone.utc)


def parse_timestamp(ts):
    if not isinstance(ts, str):
        return None
    try:
        dt = datetime.datetime.fromisoformat(ts.replace('Z', '+00:00'))
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt
    except Exception:
        return None


request_rate_series = default_metric('request_rate')
error_rate_series = default_metric('error_rate')
