def normalize_series(series, transform=None):
    normalized = []
    for point in series:
        ts = parse_timestamp(safe_get(point, 'timestamp'))
        if ts is None:
            continue
        value = safe_get(point, 'value')
        try:
            numeric = float(value)
        except (TypeError, ValueError):
            continue
        if transform is not None:
            try:
                numeric = transform(numeric)
            except Exception:
                continue
        dict_point = {
            'timestamp': ts,
            'value': numeric
        }
        normalized.append(dict_point)
    normalized.sort(key=lambda x: x['timestamp'])
    return normalized


request_rate = normalize_series(request_rate_series)
error_rate = normalize_series(error_rate_series)
latency_p99 = normalize_series(latency_p99_series)


def bucketize(series, bucket_minutes=5, now=None):
    if now is None:
        now = now_dt
    buckets = {}
    for point in series:
        ts = point['timestamp']
        delta = now - ts
        if delta.total_seconds() < 0:
            delta_min = 0
        else:
            delta_min = int(delta.total_seconds() // 60)
        bucket_index = delta_min // bucket_minutes
        bucket_key = bucket_index
        if bucket_key not in buckets:
            buckets[bucket_key] = {
                'values': [],
                'sample_count': 0
            }
        buckets[bucket_key]['values'].append(point['value'])
        buckets[bucket_key]['sample_count'] += 1
    result = []
    for bucket_index in sorted(buckets.keys()):
        values = buckets[bucket_index]['values']
        if not values:
            continue
        avg = sum(values) / len(values)
        max_val = max(values)
        count = len(values)
        result.append({
            'bucket_index': bucket_index,
            'start_age_minutes': bucket_index * bucket_minutes,
            'end_age_minutes': (bucket_index + 1) * bucket_minutes - 1,
            'average': avg,
            'max': max_val,
            'count': count
        })
    return result


req_buckets = bucketize(request_rate, 5)
err_buckets = bucketize(error_rate, 5)
lat_buckets = bucketize(latency_p99, 5)


def compute_change(current_bucket, previous_bucket):
    if previous_bucket is None or current_bucket is None:
        return None
    prev_avg = previous_bucket['average']
    curr_avg = current_bucket['average']
    if prev_avg == 0:
        return None
    return (curr_avg - prev_avg) / prev_avg


def find_bucket(buckets, age_minutes):
    for b in buckets:
        if b['start_age_minutes'] <= age_minutes < b['end_age_minutes'] + 1:
            return b
    return None


current_req_bucket = find_bucket(req_buckets, 0)
previous_req_bucket = find_bucket(req_buckets, 5)
current_err_bucket = find_bucket(err_buckets, 0)
previous_err_bucket = find_bucket(err_buckets, 5)
current_lat_bucket = find_bucket(lat_buckets, 0)
previous_lat_bucket = find_bucket(lat_buckets, 5)

req_change = compute_change(current_req_bucket, previous_req_bucket)
err_change = compute_change(current_err_bucket, previous_err_bucket)
lat_change = compute_change(current_lat_bucket, previous_lat_bucket)

log_entries = default_log_entries()

def extract_error_groups(logs):
    groups = {}
    for entry in logs:
        message = safe_get(entry, 'message', '')
        if not isinstance(message, str):
            message = str(message)
        service = safe_get(entry, 'service', 'checkout')
        severity = safe_get(entry, 'severity', 'error')
        stack = safe_get(entry, 'stack_trace', '')
        if not isinstance(stack, str):
            stack = str(stack)
        error_type = 'unknown'
        match = re.search(r'([A-Za-z_][A-Za-z0-9_.]*Error)', message)
        if match:
            error_type = match.group(1)
        elif 'exception' in message.lower():
            error_type = 'exception'
        key = (error_type, service, severity)
        if key not in groups:
            groups[key] = {
                'error_type': error_type,
                'service': service,
                'severity': severity,
                'count': 0,
                'sample_messages': [],
                'first_seen': None,
                'last_seen': None
            }
        groups[key]['count'] += 1
        ts = parse_timestamp(safe_get(entry, 'timestamp'))
        if ts is not None:
            if groups[key]['first_seen'] is None or ts < groups[key]['first_seen']:
                groups[key]['first_seen'] = ts
            if groups[key]['last_seen'] is None or ts > groups[key]['last_seen']:
                groups[key]['last_seen'] = ts
        if len(groups[key]['sample_messages']) < 3:
            groups[key]['sample_messages'].append(message[:200])
    return list(groups.values())


error_groups = extract_error_groups(log_entries)


def correlate_with_deployment(error_groups, deployment_time):
    if deployment_time is None:
        return []
    for group in error_groups:
        first = group.get('first_seen')
        last = group.get('last_seen')
        over_lap = False
        if first is not None and last is not None:
            over_lap = first <= deployment_time and last >= deployment_time
        group['correlated_with_deployment'] = over_lap
    return error_groups


deployment_ts = parse_timestamp(safe_get(deployment, 'timestamp'))
deployment_sha = safe_get(deployment, 'sha') or safe_get(deployment, 'commit')
if deployment_sha is None:
    deployment_sha = 'unknown'

error_groups = correlate_with_deployment(error_groups, deployment_ts)

deployment_metadata = safe_get(deployment, 'metadata', {})
if not isinstance(deployment_metadata, dict):
    deployment_metadata = {}


def evaluate_config_drift():
    expected_keys = ['max_connections', 'timeout_ms', 'feature_flags']
    drift_checks = []
    if not isinstance(config, dict):
        config_dict = {}
    else:
        config_dict = config
    for key in expected_keys:
        expected = safe_get(config_dict, key)
        if expected is None:
            drift_checks.append({
                'key': key,
                'expected': None,
                'actual': None,
                'status': 'missing'
            })
        else:
            actual = safe_get(deployment_metadata, key)
            if actual == expected:
                drift_checks.append({
                    'key': key,
                    'expected': expected,
                    'actual': actual,
                    'status': 'ok'
                })
            else:
                drift_checks.append({
                    'key': key,
                    'expected': expected,
                    'actual': actual,
                    'status': 'drift'
                })
    return drift_checks


drift_checks = evaluate_config_drift()


def evaluate_thresholds(curr_bucket, metric_name, threshold, comparison='above'):
    if curr_bucket is None:
        return {
            'metric': metric_name,
            'status': 'no_data',
            'current': None,
            'threshold': threshold,
            'exceeded': False
        }
    current_value = curr_bucket['average']
    exceeded = False
    if comparison == 'above':
        exceeded = current_value > threshold
    elif comparison == 'below':
        exceeded = current_value < threshold
    else:
        exceeded = False
    status = 'exceeded' if exceeded else 'ok'
    return {
        'metric': metric_name,
        'status': status,
        'current': current_value,
        'threshold': threshold,
        'exceeded': exceeded
    }


thresholds = [
    evaluate_thresholds(current_err_bucket, 'error_rate', 0.02, 'above'),
    evaluate_thresholds(current_lat_bucket, 'latency_p99', 0.5, 'above')
