    for t in thresholds:
        if t['exceeded']:
            score -= 25
    if req_change is not None and abs(req_change) > 0.2:
        score -= 10
    score = max(0, min(100, score))
    return score


confidence = compute_confidence_score(error_groups, drift_checks, thresholds, req_change)


def decide_release_gate(confidence_score, error_groups, drift_checks):
    if confidence_score < 50:
        return 'block'
    if len(error_groups) > 0 and any(g['correlated_with_deployment'] for g in error_groups):
        return 'block'
    if any(check['status'] == 'drift' for check in drift_checks):
        return 'investigate'
    if confidence_score < 80:
        return 'investigate'
    return 'approve'


gate = decide_release_gate(confidence, error_groups, drift_checks)


summary_lines = []
summary_lines.append('Checkout release readiness snapshot for 6h period')
summary_lines.append('Metrics: request_rate={}, error_rate={}, latency_p99={}'.format(
